WITH flattened_attrs AS (SELECT id, created_at, items, ship_to, attributes, ship_to.zip AS ship_zip, ship_to.city AS ship_city, attributes['device'] AS device, TRANSFORM(items, x -> x.product_id) AS product_ids, COALESCE(attributes['utm_source'], 'direct') AS utm_source_or_default FROM carts WHERE created_at >= '2023-09-01') SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) FILTER (WHERE ship_city = 'Berlin') AS berlin_rows, COUNT(*) FILTER (WHERE ship_city = 'Singapore') AS singapore_rows, MIN(created_at) AS first_created_at, MAX(created_at) AS last_seen, SIZE(COLLECT_SET(ship_city)) AS num_ship_cities, SORT_ARRAY(COLLECT_SET(ship_city)) AS ship_city_list, GROUPING_ID() AS grouping_level FROM flattened_attrs GROUP BY GROUPING SETS ((DATE_TRUNC('HOUR', created_at), DATE_TRUNC('DAY', created_at)), (DATE_TRUNC('HOUR', created_at)), ())
